import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const l=JSON.parse('{"title":"Sheria ya Uhakikisho wa Matibabu","description":"","frontmatter":{},"headers":[],"relativePath":"sw/44-医疗保障法.md","filePath":"sw/44-医疗保障法.md","lastUpdated":1789183869000}'),k={name:"sw/44-医疗保障法.md"};function h(m,a,o,w,e,b){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="sheria-ya-uhakikisho-wa-matibabu" tabindex="-1">Sheria ya Uhakikisho wa Matibabu <a class="header-anchor" href="#sheria-ya-uhakikisho-wa-matibabu" aria-label="Permalink to &quot;Sheria ya Uhakikisho wa Matibabu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>44</td></tr><tr><td>Moduli</td><td>Mfumo wa Kisheria na Muundo wa Usimamizi</td></tr><tr><td>Maneno muhimu ya msingi</td><td>Haki ya Matibabu, Matibabu ya Usawa, Matibabu ya Majeraha ya Mazoezi, Afya ya Maisha, Mfumo wa Bima ya Afya</td></tr></tbody></table><h2 id="_1-lengo-la-kisheria-na-kanuni-za-msingi" tabindex="-1">1. Lengo la Kisheria na Kanuni za Msingi <a class="header-anchor" href="#_1-lengo-la-kisheria-na-kanuni-za-msingi" aria-label="Permalink to &quot;1. Lengo la Kisheria na Kanuni za Msingi&quot;">​</a></h2><p>《Sheria ya Uhakikisho wa Matibabu》 ni moja ya sheria tano za msingi za ustaarabu wa usawa wa nanga, na lengo lake ni kuhakikisha haki ya afya na haki ya matibabu ya kila kiumbe ndani ya Hengyuanzhou, kujenga mfumo wa matibabu wa usawa unaofunika kila kabila, na kuhakikisha kwamba kila kiumbe anaweza kupata matibabu ya wakati na yenye ufanisi wakati anaugua au amejeruhiwa.</p><p>Sheria hii inaweka kanuni zifuatazo za msingi:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th></tr></thead><tbody><tr><td>Kanuni ya Kipaumbele cha Afya</td><td>Afya ya maisha ni msingi wa mageuzi yote, serikali na ustaarabu huweka uhakikisho wa afya ya maisha katika nafasi ya kipaumbele</td></tr><tr><td>Kanuni ya Funiko la Jumla</td><td>Uhakikisho wa matibabu unafunika kila kiumbe, bila kujali kabila, kiwango cha mazoezi, asili, na hali ya kiuchumi</td></tr><tr><td>Kanuni ya Uchunguzi wa Viwango</td><td>Kujenga mfumo wa uchunguzi wa viwango vitatu: matibabu ya msingi, matibabu ya mkoa, matibabu ya juu, kugawa rasilimali za matibabu kwa busara</td></tr><tr><td>Kanuni ya Ushirikiano wa Kuzuia na Kutibu</td><td>Kuzuia kama msingi, kuunganisha kuzuia na kutibu, kuthamini kuzuia na urejeshaji wa majeraha ya mazoezi</td></tr><tr><td>Kanuni ya Uwezo wa Kukabiliana na Makabila</td><td>Kutoa mipango ya matibabu inayofaa kwa tabia za kibaolojia za makabila tofauti, kukataza kutumia kiwango cha kibinadamu cha kimoja</td></tr><tr><td>Kanuni ya Sifa ya Manufaa ya Umma</td><td>Huduma za matibabu za msingi zina sifa ya manufaa ya umma, haifai kuchukua haki ya matibabu ya maisha kwa madhumuni ya faida</td></tr></tbody></table><h2 id="_2-uhakikisho-wa-kisheria-wa-haki-ya-afya-ya-maisha" tabindex="-1">2. Uhakikisho wa Kisheria wa Haki ya Afya ya Maisha <a class="header-anchor" href="#_2-uhakikisho-wa-kisheria-wa-haki-ya-afya-ya-maisha" aria-label="Permalink to &quot;2. Uhakikisho wa Kisheria wa Haki ya Afya ya Maisha&quot;">​</a></h2><p>Sheria hii inabainisha wazi kwamba haki ya afya ya maisha ni haki ya msingi inayotolewa kwa kila kiumbe na Katiba ya Usawa, ikiwa ni pamoja na:</p><ol><li><strong>Haki ya Matibabu ya Msingi</strong>: Kila kiumbe ana haki ya kupokea huduma za matibabu za msingi bure, ikiwa ni pamoja na uchunguzi na matibabu ya magonjwa ya kawaida, dawa za msingi, uchunguzi wa afya wa kawaida, n.k.</li><li><strong>Haki ya Matibabu ya Dharura</strong>: Kila kiumbe ana haki ya kupokea matibabu ya dharura wakati anapopata magonjwa au majeraha ya ghafla, na taasisi za matibabu hazifai kukataza matibabu ya dharura kwa sababu yoyote.</li><li><strong>Haki ya Matibabu ya Majeraha ya Mazoezi</strong>: Wanaofanya mazoezi wanaopata majeraha kama vile usumbufu wa nishati, jeraha la mishipa, kupoteza mwongozo wa mazoezi, n.k. wakati wa mchakato wa mazoezi wana haki ya kupokea matibabu ya kitaaluma.</li><li><strong>Haki ya Idhini ya Kujua</strong>: Mgonjwa ana haki ya kujua hali yake mwenyewe, mpango wa matibabu, hatari, na utabiri, na ana haki ya kuchagua au kukataza mpango wa matibabu.</li><li><strong>Haki ya Ulinzi wa Faragha</strong>: Taarifa za matibabu na data za mwili za mgonjwa zinalindwa na sheria, hazifai kufichuliwa au kutumika kwa madhumuni mengine bila idhini ya mgonjwa.</li><li><strong>Haki ya Uhakikisho wa Urejeshaji</strong>: Wagonjwa walioaugua au waliojeruhiwa wana haki ya kupokea matibabu ya urejeshaji na vifaa vya msaada, na kuwasaidia kurejesha uwezo wa kazi na maisha.</li></ol><h2 id="_3-muundo-wa-mfumo-wa-matibabu-wa-usawa" tabindex="-1">3. Muundo wa Mfumo wa Matibabu wa Usawa <a class="header-anchor" href="#_3-muundo-wa-mfumo-wa-matibabu-wa-usawa" aria-label="Permalink to &quot;3. Muundo wa Mfumo wa Matibabu wa Usawa&quot;">​</a></h2><p>Mfumo wa matibabu wa ustaarabu wa usawa wa nanga umegawanyika katika viwango vitatu, na mifumo ya rufaa na ushirikiano imeanzishwa kati ya viwango:</p><table tabindex="0"><thead><tr><th>Kiwango</th><th>Jina</th><th>Kazi</th><th>Eneo la Funiko</th></tr></thead><tbody><tr><td>Kiwango cha kwanza</td><td>Kituo cha Matibabu cha Msingi</td><td>Uchunguzi na matibabu ya magonjwa ya kawaida, kuzuia na utunzaji wa afya, uchunguzi wa msingi, usafirishaji wa dharura</td><td>Jumuiya/kijiji/ndogo viwango</td></tr><tr><td>Kiwango cha pili</td><td>Kituo cha Matibabu cha Mkoa</td><td>Uchunguzi wa kitaalamu, matibabu ya upasuaji, matibabu ya awali ya majeraha ya mazoezi, urejeshaji</td><td>Jiji/mkoa/viwango vya kati</td></tr><tr><td>Kiwango cha tatu</td><td>Hospitali Kuu ya Matibabu ya Juu</td><td>Magonjwa magumu na makali, majeraha ya mazoezi ya juu, magonjwa ya kikoa cha ufahamu, magonjwa magumu ya kati ya makabila</td><td>Kiini cha ustaarabu/viwango vikubwa</td></tr></tbody></table><p>Zaidi ya hayo, &quot;Taaluma ya Majeraha ya Mazoezi&quot; imeanzishwa: inashughulikia maalum aina mbalimbali za majeraha wakati wa mchakato wa mazoezi, ikiwa ni pamoja na mzigo wa ziada wa nishati, kuvunjika kwa mishipa, uvamizi wa pepo wa ndani, kiwewe cha roho, n.k., na imejengwa na wafanyakazi wa matibabu waliozoea sheria za mazoezi.</p><h2 id="_4-sanduku-la-uhakikisho-wa-matibabu" tabindex="-1">4. Sanduku la Uhakikisho wa Matibabu <a class="header-anchor" href="#_4-sanduku-la-uhakikisho-wa-matibabu" aria-label="Permalink to &quot;4. Sanduku la Uhakikisho wa Matibabu&quot;">​</a></h2><p>Sanduku la uhakikisho wa matibabu ni msingi wa kiuchumi wa utendaji wa mfumo wa matibabu wa usawa, na vyanzo vyake vinajumuisha:</p><ul><li>Gawio la akiba ya umma (chanzo kuu)</li><li>Kibali cha uhakikisho wa matibabu katika mfumo wa mkataba wa uzalishaji wa pamoja</li><li>Michango ya kijamii</li><li>Pato la uwekezaji wa sanduku</li></ul><p>Eneo la malipo ya sanduku linajumuisha: gharama za huduma za matibabu za msingi, gharama za dharura, gharama za matibabu ya majeraha ya mazoezi, gharama za dawa za msingi, gharama za urejeshaji, n.k. Mgonjwa binafsi anahitaji kulipa gharama ndogo ya kujilipa tu, na msamaha unatolewa kwa wale walio na ugumu wa kiuchumi.</p><h2 id="_5-taasisi-za-matibabu-na-wafanyakazi-wa-matibabu" tabindex="-1">5. Taasisi za Matibabu na Wafanyakazi wa Matibabu <a class="header-anchor" href="#_5-taasisi-za-matibabu-na-wafanyakazi-wa-matibabu" aria-label="Permalink to &quot;5. Taasisi za Matibabu na Wafanyakazi wa Matibabu&quot;">​</a></h2><ul><li><strong>Taasisi za Matibabu za Umma</strong>: Zimeanzishwa na serikali au jumuiya ya ustaarabu, zinabeba jukumu la huduma za matibabu za msingi na kazi za afya ya umma, na fedha zinahakikishwa na sanduku la uhakikisho wa matibabu.</li><li><strong>Taasisi za Matibabu za Kibinafsi</strong>: Zimeanzishwa na nguvu za jamii kulingana na sheria, zinaweza kutoa huduma za matibabu za hali ya juu, lakini lazima zikubali ushirikiano wa idara inayohusiana ya afya, na hazifai kukataza wagonjwa wa dharura.</li><li><strong>Taasisi za Matibabu za Kati ya Makabila</strong>: Taasisi za matibabu za kitaalamu zilizozingatiwa mahitaji ya kibaolojia ya makabila maalum, na zimejengwa na wafanyakazi wa matibabu wa makabila mengine.</li><li><strong>Haki na Wajibu wa Wafanyakazi wa Matibabu</strong>: Wafanyakazi wa matibabu hufurahia haki kama vile ulinzi wa utekelezaji, malipo yanayofaa, mafunzo ya kitaaluma, n.k., na wakati huo huo wana wajibu wa kuokoa maisha, kuheshimu wagonjwa, kulinda siri za matibabu, n.k.</li></ul><h2 id="_6-afya-ya-umma-na-kuzuia" tabindex="-1">6. Afya ya Umma na Kuzuia <a class="header-anchor" href="#_6-afya-ya-umma-na-kuzuia" aria-label="Permalink to &quot;6. Afya ya Umma na Kuzuia&quot;">​</a></h2><p>Serikali inajenga mfumo wa afya ya umma, na hutekeleza kazi zifuatazo:</p><ol><li>Ufuatiliaji na kuzuia na kudhibiti magonjwa ya kuambukiza, kujenga mfumo wa tahadhari ya janga la kati ya viwango.</li><li>Uchunguzi wa afya ya jumla na usimamizi wa rekodi za afya.</li><li>Ushirikiano wa usalama wa mazoezi na mwongozo wa kuzuia majeraha ya mazoezi.</li><li>Ufuatiliaji wa afya ya mazingira na usalama wa chakula na dawa.</li><li>Majibu ya dharura kwa matukio ya ghafla ya afya ya umma.</li></ol><h2 id="_7-wajibu-wa-kisheria" tabindex="-1">7. Wajibu wa Kisheria <a class="header-anchor" href="#_7-wajibu-wa-kisheria" aria-label="Permalink to &quot;7. Wajibu wa Kisheria&quot;">​</a></h2><p>Shughuli zinazovunja masharti ya sheria hii zitabeba wajibu ufuatao kulingana na ukubwa wa makosa:</p><ul><li>Taasisi za matibabu zinazokataza wagonjwa wa dharura, kuamriwa kurekebisha na kupigwa faini, katika visa vya matokeo makali leseni ya utekelezaji inakatiwa.</li><li>Wafanyakazi wa matibabu wanaosababisha uharibifu kwa mgonjwa kwa kutotarajia kwa makini, wanabeba wajibu wa fidia, katika visa vizito uwezo wa utekelezaji unakatiwa.</li><li>Taasisi za matibabu zinazochukua malipo ya kikatili au kufanya matibabu ya ziada, kuamriwa kurejesha malipo na kupigwa faini.</li><li>Kufichua faragha ya matibabu ya mgonjwa, kubeba fidia ya uharibifu wa kiakili, katika visa vizito wajibu wa jinai unafuatiliwa.</li><li>Kuzalisha au kuuza dawa za uwongo au dawa za ubora wa chini, mapato ya kikatili yanakamatwa na kupigwa faini, ikiwa inajenga uhalishi wajibu wa jinai unafuatiliwa.</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>《Sheria ya Uhakikisho wa Matibabu》 ni udhishaji wa dhana ya &quot;kila mtu ana njia&quot; ya ustaarabu wa usawa wa nanga katika sehemu ya afya. Kupitia kujenga mfumo wa uhakikisho wa matibabu wenye funiko la jumla, kuanzisha taaluma ya majeraha ya mazoezi, na kuhakikisha haki ya matibabu ya dharura, inahakikisha kwamba kila kiumbe anaweza kupata matibabu ya wakati wakati anaugua au amejeruhiwa, na inaimarisha msingi wa afya kwa maendeleo ya pamoja ya kila kabila.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Kanuni za Msingi za Katiba ya Usawa)</li><li>38-共生医疗体系 (Mfumo wa Matibabu wa Usawa)</li><li>45-住房保障法 (Sheria ya Uhakikisho wa Makazi)</li><li>08-人人有路保障体系 (Mfumo wa Uhakikisho wa Kila Mtu Ana Njia)</li></ul>',29)])])}const r=i(k,[["render",h]]);export{l as __pageData,r as default};
